package stepdefinitions;

import io.cucumber.java.en.Given;
import io.cucumber.java.en.When;
import io.cucumber.java.en.Then;
import org.junit.Assert;
import pages.AuthenticationPage;
import pages.CoreFunctionalityPage;

public class AuthenticationSteps {
    private final AuthenticationPage authenticationPage;
    private final CoreFunctionalityPage coreFunctionalityPage;

    public AuthenticationSteps(AuthenticationPage authenticationPage, CoreFunctionalityPage coreFunctionalityPage) {
        this.authenticationPage = authenticationPage;
        this.coreFunctionalityPage = coreFunctionalityPage;
    }

    @Given("the user is on the login page")
    public void the_user_is_on_the_login_page() {
        coreFunctionalityPage.navigateToLoginPage();
    }

    @When("the user enters registered email address {string}")
    public void the_user_enters_registered_email_address(String email) {
        authenticationPage.loginUser(email, null);
    }

    @When("the user enters the correct password {string}")
    public void the_user_enters_the_correct_password(String password) {
        authenticationPage.loginUser(null, password);
    }

    @Then("the user is redirected to the dashboard")
    public void the_user_is_redirected_to_the_dashboard() {
        Assert.assertTrue("User should be redirected to the dashboard", coreFunctionalityPage.isDashboardVisible());
    }

    @Then("the welcome message displays the user's name")
    public void the_welcome_message_displays_the_user_s_name() {
        String expectedMessage = "Welcome, Test User!";
        String actualMessage = coreFunctionalityPage.getWelcomeMessage();
        Assert.assertEquals("Expected welcome message", expectedMessage, actualMessage);
    }

    @Then("the navigation bar shows {string} link")
    public void the_navigation_bar_shows_link(String linkText) {
        Assert.assertTrue("Navigation bar should show " + linkText + " link", coreFunctionalityPage.isLinkVisible(linkText));
    }

