import org.openqa.selenium.support.ui.WebDriverWait;

import java.time.Duration;

public class WaitUtils {
    private static WebDriver driver;

    public WaitUtils(WebDriver driver) {
        WaitUtils.driver = driver;
    }

    public static void waitForTextPresent(By locator, String text) {
        new WebDriverWait(driver, Duration.ofSeconds(20))
                .until(ExpectedConditions.textToBePresentInElementLocated(locator, text));
    }

    public static void waitForUrlContains(String fragment) {
        new WebDriverWait(driver, Duration.ofSeconds(20))
                .until(ExpectedConditions.urlContains(fragment));
    }

    public static void waitForAttributeContains(By locator, String attribute, String value) {
        new WebDriverWait(driver, Duration.ofSeconds(20))
                .until(ExpectedConditions.attributeContains(locator, attribute, value));
    }

    public static void waitForInvisibility(By locator) {
        new WebDriverWait(driver, Duration.ofSeconds(20))
                .until(ExpectedConditions.invisibilityOfElementLocated(locator));
    }
}
