        basePage.navigateToRegistrationPage();
    }

    @When("the user enters email {string}")
    public void the_user_enters_email(String email) {
        registrationPage.enterEmail(email);
    }

    @When("the user enters password {string}")
    public void the_user_enters_password(String password) {
        registrationPage.enterPassword(password);
    }

    @When("the user submits the registration form")
    public void the_user_submits_the_registration_form() {
        registrationPage.clickRegister();
    }

    @Then("the user is redirected to a success page")
    public void the_user_is_redirected_to_a_success_page() {
        Assert.assertTrue("User is not redirected to success page", basePage.isOnSuccessPage());
    }

    @Then("the toast message should be {string}")
    public void the_toast_message_should_be(String expectedMessage) {
        String actualMessage = registrationPage.getToastMessage();
        Assert.assertEquals("Expected toast message", expectedMessage, actualMessage);
