        new WebDriverWait(driver, 20).until(ExpectedConditions.textToBe(locator, text));
    }

    public static void waitForUrlContains(String fragment) {
        new WebDriverWait(driver, 20).until(ExpectedConditions.urlContains(fragment));
    }

    public static void waitForAttributeContains(By locator, String attribute, String value) {
        new WebDriverWait(driver, 20).until(ExpectedConditions.attributeContains(locator, attribute, value));
    }

    public static void waitForInvisibility(By locator) {
        new WebDriverWait(driver, 20).until(ExpectedConditions.invisibilityOfElementLocated(locator));
    }
}
